package com.shopsphere.controller; import com.shopsphere.model.User;import com.shopsphere.service.UserService;import jakarta.servlet.annotation.WebServlet;import jakarta.servlet.http.*;import java.io.*;@WebServlet("/login") public class LoginServlet extends HttpServlet{private final UserService s=new UserService();protected void doPost(HttpServletRequest r,HttpServletResponse p)throws IOException{try{String role="ADMIN".equalsIgnoreCase(r.getParameter("role"))?"ADMIN":"CUSTOMER";User u=s.login(r.getParameter("email"),r.getParameter("password"),role);if(u==null){p.sendRedirect("login.jsp?error=Invalid+credentials");return;}r.getSession().setAttribute("user",u);p.sendRedirect(r.getContextPath()+("ADMIN".equals(role)?"/admin/dashboard.jsp":"/products"));}catch(Exception e){throw new IOException(e);}}}
